// Types from team-setup/state/03-contract-freeze/contract.md, plus additive
// optional fields the app uses (lat/lon, distributions, leave-home time).

export type Station = {
  evaNumber: string
  name: string
  lat?: number
  lon?: number
}

export type Leg = {
  trainId: string // e.g. "RB 16"
  trainNumber?: string
  from: Station
  to: Station
  plannedDeparture: string // ISO 8601 with offset
  plannedArrival: string
  transferMinutes?: number // planned transfer to the next leg
}

export type Journey = {
  id: string
  legs: Leg[]
  source: "db-share" | "manual" | "seed"
}

export type Confidence = "low" | "medium" | "high"

export type Explained<T> = {
  value: T
  reasoning: string
  sources: string[]
  confidence: Confidence
}

export type DelayDistribution = {
  bins: string[] // e.g. ["≤5", "5–15", "15–30", ">30", "cancelled"]
  probs: number[]
}

export type LegDelay = {
  trainId: string
  expectedDelayMinutes: Explained<number>
  missProbability: Explained<number> // 0..1, chance this transfer breaks
  distribution?: DelayDistribution
  quantiles?: { p10: number; p50: number; p90: number }
  pCancel?: number
  // Full per-minute pmf when the backend provides it; used by the buffer slider.
  probs?: number[]
}

export type Prediction = {
  journeyId: string
  legs: LegDelay[]
  planFailProbability: Explained<number>
  modelId: string
}

export type Verdict = "good" | "add-buffer" | "take-alternative"

export type Recommendation = {
  verdict: Verdict
  advice: Explained<string>
  bufferMinutes?: number
  alternative?: Journey
  leaveHomeBy?: string
  chosenDeparture?: string
}

export type RerouteOption = {
  journey: Journey
  planFailProbability: Explained<number>
  arrivalDelayMinutes: number
  label: string
}

export type Reroute = {
  station: Station
  options: RerouteOption[]
}

export type CauseFamilies = {
  works: number
  weather: number
  technical: number
  knock_on: number
  staff: number
  external: number
  unattributed: number
}

export type Causes = {
  station: Station
  attributionRate: number
  families: CauseFamilies
  top: { code: number; text: string; share: number }[]
  sparkline7d: { date: string; meanDelayMin: number }[]
  source: string
}

export type Proof = {
  metric: string
  label: string
  lowerIsBetter: boolean
  n: number
  split: string
  models: { name: string; value: number; highlight?: boolean }[]
}

// Port of app/agents/src/features/db_delay/trip/connection.py.
// A change works when both trains run and
//   arrival delay - departure delay <= planned buffer - minimum transfer.
// Trains are treated as independent (optimistic when one disruption hits both).

import type { Journey, LegDelay, Prediction } from "./contract"

export type TrainForecast = { probs: number[]; pCancel?: number }

export const LATE_MINUTES = 6
export const MIN_TRANSFER_MINUTES = 5

export function normalise(probs: number[]): Float64Array {
  let total = 0
  for (const p of probs) total += p
  if (!(total > 0)) throw new Error("delay distribution has no mass")
  return Float64Array.from(probs, (p) => p / total)
}

/** P(both run and A - D <= floor(buffer - minTransfer)). */
export function changeProbability(
  arriving: TrainForecast,
  departing: TrainForecast,
  plannedBuffer: number,
  minTransfer: number,
): number {
  const a = normalise(arriving.probs)
  const d = normalise(departing.probs)
  const slack = Math.floor(plannedBuffer - minTransfer)
  // tail[k] = P(D >= k)
  const tail = new Float64Array(d.length + 1)
  for (let k = d.length - 1; k >= 0; k--) tail[k] = tail[k + 1] + d[k]
  let made = 0
  for (let i = 0; i < a.length; i++) {
    const k = i - slack // need D >= i - slack
    made += a[i] * (k <= 0 ? 1 : k >= d.length ? 0 : tail[k])
  }
  return (1 - (arriving.pCancel ?? 0)) * (1 - (departing.pCancel ?? 0)) * made
}

export function journeyProbability(
  changes: [TrainForecast, TrainForecast, number, number][],
  finalArrival?: TrainForecast,
  arrivalSlack?: number,
) {
  const perChange = changes.map(([a, d, b, m]) => changeProbability(a, d, b, m))
  let success = perChange.reduce((p, x) => p * x, 1)
  if (finalArrival && arrivalSlack != null) {
    const pmf = normalise(finalArrival.probs)
    let onTime = 0
    for (let k = 0; k <= Math.floor(arrivalSlack) && k < pmf.length; k++) onTime += pmf[k]
    success *= (1 - (finalArrival.pCancel ?? 0)) * onTime
  }
  return { changeProbabilities: perChange, planSuccess: success, planFail: 1 - success }
}

export function point(minutes: number, size = 240, pCancel = 0): TrainForecast {
  const probs = new Array<number>(size).fill(0)
  probs[Math.min(minutes, size - 1)] = 1
  return { probs, pCancel }
}

export function quantile(probs: number[], q: number): number {
  const p = normalise(probs)
  let c = 0
  for (let k = 0; k < p.length; k++) {
    c += p[k]
    if (c >= q) return k
  }
  return p.length - 1
}

/** Geometric pmf whose median lands on `median` minutes (mirrors the backend mock). */
export function geometricPmf(median: number, size = 240): number[] {
  const q = Math.pow(0.5, 1 / (Math.max(median, 0) + 1))
  const probs = new Array<number>(size)
  for (let k = 0; k < size; k++) probs[k] = (1 - q) * Math.pow(q, k)
  return probs
}

function forecastOf(leg: LegDelay): TrainForecast {
  const probs = leg.probs && leg.probs.length ? leg.probs : geometricPmf(leg.expectedDelayMinutes.value)
  return { probs, pCancel: leg.pCancel ?? 0 }
}

function minutesBetween(a: string, b: string): number {
  return Math.round((new Date(b).getTime() - new Date(a).getTime()) / 60000)
}

export function transferBuffer(journey: Journey, i: number): number {
  const leg = journey.legs[i]
  const next = journey.legs[i + 1]
  if (!next) return 0
  return leg.transferMinutes ?? minutesBetween(leg.plannedArrival, next.plannedDeparture)
}

/**
 * Re-chain a prediction in the browser with extra minutes added at one transfer
 * (or every transfer when index is -1). Used by the buffer slider.
 */
export function rechain(
  journey: Journey,
  prediction: Prediction,
  extraMinutes: number,
  atTransfer = -1,
  minTransfer = MIN_TRANSFER_MINUTES,
): { legs: number[]; planFail: number } {
  const changes: [TrainForecast, TrainForecast, number, number][] = []
  for (let i = 0; i < journey.legs.length - 1; i++) {
    const arr = forecastOf(prediction.legs[i])
    const depLeg = prediction.legs[i + 1]
    const dep: TrainForecast = { probs: geometricPmf(depLeg.expectedDelayMinutes.value * 0.4), pCancel: depLeg.pCancel ?? 0 }
    const extra = atTransfer === -1 || atTransfer === i ? extraMinutes : 0
    changes.push([arr, dep, transferBuffer(journey, i) + extra, minTransfer])
  }
  const r = journeyProbability(changes)
  const legs = r.changeProbabilities.map((p) => 1 - p)
  legs.push(0)
  return { legs, planFail: r.planFail }
}

import type { Journey, Station } from "./contract"
import raw from "./stations.json"

export type StationEntry = { name: string; evaNumber: string; lat: number; lon: number; aliases: string[] }

export const STATIONS: StationEntry[] = raw as StationEntry[]

export function normaliseName(s: string): string {
  return s
    .toLowerCase()
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/ß/g, "ss")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/hauptbahnhof/g, "hbf")
    .replace(/[()\-.,/]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
}

const byEva = new Map<string, StationEntry>()
const byName = new Map<string, StationEntry>()
for (const st of STATIONS) {
  byEva.set(st.evaNumber, st)
  byName.set(normaliseName(st.name), st)
  for (const a of st.aliases) byName.set(normaliseName(a), st)
}

export function lookupStation(q: { evaNumber?: string; name?: string }): StationEntry | undefined {
  if (q.evaNumber && byEva.has(q.evaNumber)) return byEva.get(q.evaNumber)
  if (!q.name) return undefined
  const n = normaliseName(q.name)
  if (byName.has(n)) return byName.get(n)
  const stripped = n.replace(/\b(hbf|hb)\b/g, "").trim()
  for (const [k, v] of byName) if (k.replace(/\b(hbf|hb)\b/g, "").trim() === stripped) return v
  for (const [k, v] of byName) if (k.startsWith(n) || n.startsWith(k)) return v
  return undefined
}

export function searchStations(q: string, limit = 8): StationEntry[] {
  const n = normaliseName(q)
  if (!n) return []
  const seen = new Set<string>()
  const out: StationEntry[] = []
  for (const st of STATIONS) {
    const hay = [st.name, ...st.aliases].map(normaliseName)
    if (hay.some((h) => h.includes(n)) && !seen.has(st.evaNumber)) {
      seen.add(st.evaNumber)
      out.push(st)
      if (out.length >= limit) break
    }
  }
  return out
}

export function withCoords(station: Station): Station {
  if (station.lat != null && station.lon != null) return station
  const hit = lookupStation(station)
  return hit ? { ...station, evaNumber: station.evaNumber || hit.evaNumber, lat: hit.lat, lon: hit.lon } : station
}

export function hydrateCoords(journey: Journey): Journey {
  return { ...journey, legs: journey.legs.map((l) => ({ ...l, from: withCoords(l.from), to: withCoords(l.to) })) }
}

import type { Journey, Leg } from "./contract"

export type LngLat = [number, number]

export function legLine(leg: Leg): LngLat[] | null {
  if (leg.from.lon == null || leg.from.lat == null || leg.to.lon == null || leg.to.lat == null) return null
  return [
    [leg.from.lon, leg.from.lat],
    [leg.to.lon, leg.to.lat],
  ]
}

export function journeyBounds(journey: Journey): [LngLat, LngLat] | null {
  let minLon = Infinity, minLat = Infinity, maxLon = -Infinity, maxLat = -Infinity
  for (const leg of journey.legs) {
    for (const s of [leg.from, leg.to]) {
      if (s.lon == null || s.lat == null) continue
      minLon = Math.min(minLon, s.lon); maxLon = Math.max(maxLon, s.lon)
      minLat = Math.min(minLat, s.lat); maxLat = Math.max(maxLat, s.lat)
    }
  }
  if (!isFinite(minLon)) return null
  return [[minLon, minLat], [maxLon, maxLat]]
}

export function riskLevel(p: number): "low" | "mid" | "high" {
  if (p < 0.15) return "low"
  if (p < 0.4) return "mid"
  return "high"
}

export const RISK_COLOUR = { low: "#34d399", mid: "#fbbf24", high: "#f87171", none: "#8b8bff" } as const

export function riskColour(p: number | undefined): string {
  if (p == null) return RISK_COLOUR.none
  return RISK_COLOUR[riskLevel(p)]
}

